CREATE TABLE IF NOT EXISTS joint_state (
    joint_name VARCHAR(128) NOT NULL PRIMARY KEY,
    position DOUBLE NOT NULL,
    CONSTRAINT fk_joint_state_model FOREIGN KEY (joint_name) REFERENCES ps_joint (joint_name)
