package com.example.starter.scene.model;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.util.List;

/**
 * Planning Scene 批量修改请求。
 * <p>一次请求可同时包含对象增改删/重命名、关节更新、机器人姿态更新和 attach/detach；
 * 任一操作非法则整批回滚。
 *
 * @param requestId        调用方生成的请求唯一 ID，用于幂等去重
 * @param expectedVersion  调用方基于的场景版本；过期返回 409
 * @param objects          碰撞对象操作列表，可为空
 * @param joints           关节更新列表，可为空
 * @param robotPose        新的机器人基座位姿，为空表示不更新
 * @param attachments      附着物操作列表，可为空
 */
public record SceneUpdateRequest(
        @NotBlank String requestId,
        @NotNull Long expectedVersion,
        @Valid List<ObjectCommand> objects,
        @Valid List<JointUpdate> joints,
        @Valid RobotPose robotPose,
        @Valid List<AttachmentCommand> attachments) {
}

package com.example.starter.scene.model;

import java.util.List;

/**
 * 场景快照视图，既可表示当前场景也可表示任意历史版本。
 *
 * @param version     快照版本号
 * @param requestId   产生该版本的请求 ID（版本 0 为 __initial__）
 * @param createdAt   提交时间（Unix 毫秒，UTC）
 * @param robotPose   该版本的机器人基座位姿
 * @param joints      该版本全部关节位置（弧度）
 * @param worldObjects 该版本位于世界集合的碰撞对象
 * @param attachments 该版本附着物（对象 ID -> Link 名）
 */
public record SceneSnapshot(
        long version,
        String requestId,
        long createdAt,
        RobotPose robotPose,
        List<JointStateView> joints,
        List<ObjectView> worldObjects,
        List<AttachmentView> attachments) {

    /**
     * 关节状态视图。
     */
    public record JointStateView(String jointName, double position) {
    }

    /**
     * 世界碰撞对象视图。
     */
    public record ObjectView(String objectId, String frameId, String payload) {
    }

    /**
     * 附着物视图。
     */
    public record AttachmentView(String objectId, String linkName) {
    }
}

package com.example.starter.scene.model;

import java.util.List;

/**
 * 成功提交修改后的响应。
 *
 * @param requestId 透传的请求 ID
 * @param version   新场景版本号
 * @param replayed  true 表示这是同 requestId 同参数请求的幂等重放，返回的是原结果
 */
public record UpdateResult(String requestId, long version, boolean replayed) {
}

package com.example.starter.scene.model;

import java.util.List;

/**
 * 版本过期冲突（HTTP 409）的响应体。
 *
 * @param requestId         冲突请求的 ID（幂等参数冲突时同样返回）
 * @param currentVersion    服务端当前版本号
 * @param expectedVersion   调用方提交的期望版本号
 * @param changedObjects    自 expectedVersion 后发生过变化的对象 ID（含新增/删除/重命名/attach/detach）
 * @param changedJoints     自 expectedVersion 后发生过变化的关节名（含位姿无关）
 * @param reason            冲突原因：VERSION_MISMATCH / IDEMPOTENT_PARAM_MISMATCH
 */
public record ConflictResponse(
        String requestId,
        long currentVersion,
        Long expectedVersion,
        List<String> changedObjects,
        List<String> changedJoints,
        String reason) {
}

package com.example.starter.scene.service;

import com.example.starter.scene.model.ConflictResponse;

/**
 * 请求与当前场景状态冲突时抛出：版本过期（VERSION_MISMATCH）
 * 或同 requestId 携带不同参数（IDEMPOTENT_PARAM_MISMATCH）。
 */
public class SceneConflictException extends RuntimeException {

    private final transient ConflictResponse response;

    public SceneConflictException(ConflictResponse response) {
        super(response.reason());
        this.response = response;
    }

    public ConflictResponse getResponse() {
        return response;
    }
}

package com.example.starter.scene.service;

/**
 * 请求本身非法（对象 ID 重复、关节超限、引用不存在、世界/附着互斥等），HTTP 400。
 * 整批操作在提交前校验，不产生任何写入。
 */
public class SceneValidationException extends RuntimeException {

    public SceneValidationException(String message) {
        super(message);
    }
}

