     * @param attachments 终态附着物（对象 ID -> Link 名）
     */
    record CommitData(
            long newVersion,
            String requestId,
            String requestHash,
            long createdAt,
            RobotPose pose,
            Map<String, Double> joints,
            Map<String, CurrentScene.SceneObject> objects,
            Map<String, String> attachments) {
    }
}

